/** Parameter keys a material uses (for cards and docs). */
export const paramKeys = (m) => ['alpha', 'eps', m.thinC ? 'thinC' : 'mu', 'muWet', 'ef', 'efWet', 'tau', 'storage', 'tr'].filter((k) => m[k]);
